const open = (c: Claim) => {
  setEditing(c.id);
  setDraft({ amount: c.amount, date: c.date, note: c.note });
  save.reset();
};

const cancel = () => {
  setEditing(null);
  setDraft(EMPTY);
  save.reset();
};

const submit = (e: FormEvent) => {
  e.preventDefault();
  save.reset();
  // The server refuses an amount that is not 0.00 or more with up to two decimals, or a bad date.
  save.mutate({ id: editing, body: draft });
};

return (
  <>
    <td data-testid="person-claimed">{claimed(counted(claims))}</td>
    <td data-testid="person-due-total">{showDue(dueCents(claimed(counted(claims)), rate))}</td>
    <td>
      <form onSubmit={submit}>
        <input
          data-testid="claim-form-amount"
          placeholder="amount"
          value={draft.amount}
          onChange={(e) => change({ amount: e.target.value })}
        />{' '}
        <input
          data-testid="claim-form-date"
          placeholder="yyyy-mm-dd"
          value={draft.date}
          onChange={(e) => change({ date: e.target.value })}
        />{' '}
        <input
          data-testid="claim-form-note"
          placeholder="note"
          claims.setNumber(sheet, claim.id(), null);
      }
      Person person = people.find(sheet, claim.person());
      String fields = changed.statusAuditFields(person.name());
      // Settling fixes the due at the person's grade rate in force on the claim's date; with no rate there is
      // nothing to fix, so it stays live.
      if (requested == ClaimStatusChange.SETTLE) {
          String pct = Rate.on(rates.list(sheet), person.grade(), LocalDate.parse(claim.date()));
          BigDecimal due = pct == null ? null
                  : new BigDecimal(claim.amount()).multiply(new BigDecimal(pct)).movePointLeft(2)
                          .setScale(2, RoundingMode.HALF_UP);
          claims.setSettledDue(sheet, claim.id(), due);
          fields += " due=" + (due == null ? "n/a" : due.toPlainString());

